class Dropdown {
  constructor({ dropdownButton, dropdownMenu }) {
    this.dropdownButton = dropdownButton;
    this.dropdownMenu = dropdownMenu;
  }

  onBtnClick = () => {
    console.log("Adding event listener to dropdown button");
    this.dropdownButton.removeEventListener("click", this.openCloseMenu);
    this.dropdownButton.addEventListener("click", (e) => {
      console.log("Unique listener triggered");
      this.openCloseMenu(e);
    });
  };

  openCloseMenu = (e) => {
    e.stopPropagation();
    e.preventDefault();
    const menuDisplayValue = this.dropdownMenu.classList.contains("hide");

    // console.log(this.dropdownMenu.classList.contains("hide"));

    console.log("menuDisplayValue", menuDisplayValue);

    if (!menuDisplayValue) {
      console.log("1");
      this.closeMenu();
      return;
    } else {
      console.log("2");
      this.openMenu();
      return;
    }
  };

  closeMenu = () => {
    console.log("closeMenu");
    this.dropdownMenu.classList.add("hide");
  };

  openMenu = () => {
    console.log("openMenu");
    this.dropdownMenu.classList.remove("hide");
  };
}

export default Dropdown;
